import styled from '@emotion/styled';
import { Card } from 'components/UI';

interface StyledBigNumberWithContentCardProps {
  $clickeable?: boolean;
  $fullWidth?: boolean;
}

export const StyledBigNumberWithContentCard = styled(Card, {
  shouldForwardProp: (prop) => !['$clickeable', '$fullWidth'].includes(prop),
})<StyledBigNumberWithContentCardProps>(({ $clickeable, $fullWidth }) => ({
  display: 'flex',
  flexDirection: 'column',
  gap: '12px',
  width: '703px',
  height: '234px',
  minWidth: '481.5px',
  maxWidth: '1470px',
  padding: '24px 32px 32px 16px',
  border: '1px solid #14141429',
  borderRadius: '16px',
  background: '#FFFFFF',
  boxShadow: 'none !important',
  transition: 'all 300ms ease-out',
  ...($clickeable && {
    cursor: 'pointer',
    '&:hover': {
      background:
        'linear-gradient(0deg, rgba(229, 182, 17, 0.04) 0%, rgba(229, 182, 17, 0.04) 100%), #FFF',
      boxShadow: '0 0 4px 0 rgba(0, 0, 0, 0.16) !important',
      transform: 'scale(1.01)',
    },
    '&.selected': {
      border: '2px solid transparent',
      borderRadius: '16px',
      background: `
            linear-gradient(#fefcf5, #fefcf5) padding-box,
            linear-gradient(216.66deg, #F5E003 0%, #D3A238 75%) border-box
          `,
    },
  }),
  ...($fullWidth && { width: '100%' }),
}));

export const StyledHeader = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '8px',
  paddingLeft: '16px',
});

interface StyledFullWidthProps {
  $fullWidth?: boolean;
}

export const StyledBody = styled.div({
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'stretch',
  gap: '24px',
});

export const StyledBigNumberSection = styled.div<StyledFullWidthProps>(
  ({ $fullWidth }) => ({
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
    marginTop: '12px',
    ...($fullWidth && {
      flex: '1 1 50%',
      width: '50%',
    }),
  }),
);

export const StyledContentSection = styled.div<StyledFullWidthProps>(
  ({ $fullWidth }) => ({
    width: '307.5px',
    height: '128px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    ...($fullWidth && {
      flex: '1 1 50%',
      width: '50%',
    }),
  }),
);
